// Obtener salida del Agente evaluador y los datos del formulario de entrada
const agentOutput = $input.item.json.output || $input.item.json.text || "";
const formData = $('On form submission').first().json;

// Extracto de campos del formulario
const tasacion = Number(formData["¿Cuál es tu tasación del producto?"]) || 0;
const comentario = (formData["¿Qué es lo que más destacarías del producto?"] || "").toLowerCase();

// 1. Determinar el nivel de interés devuelto por el agente
let nivelInteres = "nulo"; // Valor por defecto
const outputLower = agentOutput.toLowerCase();

if (outputLower.includes("alto")) {
  nivelInteres = "alto";
} else if (outputLower.includes("medio")) {
  nivelInteres = "medio";
} else if (outputLower.includes("bajo")) {
  nivelInteres = "bajo";
} else if (outputLower.includes("nulo")) {
  nivelInteres = "nulo";
}

// 2. Lógica para determinar la urgencia / atención prioritaria
// Un lead se considera urgente si es de nivel "alto" Y cumple alguna condición clave:
// - Cierta tasación mínima (ej: >= 5000)
// - Palabras clave de urgencia en los comentarios o en la respuesta del agente
const palabrasUrgentes = ["urgente", "asap", "inmediato", "cuanto antes", "hoy", "ya", "prioridad"];
const contieneUrgencia = palabrasUrgentes.some(word => comentario.includes(word) || outputLower.includes(word));

// Evaluación booleana de urgencia
const esUrgente = (nivelInteres === "alto") && (tasacion >= 1000 || contieneUrgencia);

// Estructurar la salida para los siguientes nodos
return {
  json: {
    id: $execution.id || Date.now().toString(),
    nombre: formData["Nombre"] || "",
    apellidos: formData["Apellidos"] || "",
    telefono: formData["Teléfono"] || "",
    correo: formData["Correo electrónico"] || "",
    nivel_interes: nivelInteres,
    es_urgente: esUrgente, // Booleano: true / false
    tasacion: tasacion,
    fecha_envio: new Date().toISOString(),
    mensaje_respuesta: agentOutput,
    correo_respuesta: formData["Correo electrónico"] || ""
  }
};

// Recorrer y formatear cada fila devuelta por la hoja de Google Sheets
const item = $input.item.json;

// 1. Limpieza y normalización de variables
const nivelInteres = (item.NIVEL_INTERES || "nulo").toLowerCase();
const esUrgente = String(item.ES_URGENTE).toLowerCase() === "true";

// 2. Definir la Prioridad de Lead para los informes
let prioridad = "Nulo / Otro";
if (nivelInteres === "alto" && esUrgente) {
  prioridad = "Alto - Urgente";
} else if (nivelInteres === "alto") {
  prioridad = "Alto";
} else if (nivelInteres === "medio") {
  prioridad = "Medio";
} else if (nivelInteres === "bajo") {
  prioridad = "Bajo";
}

// 3. Devolver los campos formateados y listos para el AI Agent y Looker Studio
return {
  json: {
    ID: item.ID || "",
    NOMBRE_COMPLETO: `${item.NOMBRE || ""} ${item.APELLIDOS || ""}`.trim(),
    CORREO: item.CORREO || "",
    TELEFONO: item.TELEFONO || "",
    NIVEL_INTERES: nivelInteres,
    ES_URGENTE: esUrgente,
    PRIORIDAD_LEAD: prioridad,
    FECHA_REGISTRO: item.FECHA_ENVIO_MENSAJE || item.FECHA_ENVIO || new Date().toISOString(),
    MENSAJE_RESPUESTA: item.MENSAJE_RESPUESTA || ""
  }
};

